INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('elex-collectors-edition', 51995, '2017-10-17', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/r6cmhya6x0qzvqabwbhu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/g1cfxo2ieargcc5k6pdo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ELEX: Collector''s Edition', 'Advanced in technology, civilized and with a population of billions, Magellan was a planet looking to the future. Then the meteor hit. Those who survived are now trapped in a battle to survive, a struggle to decide the fate of a planet. At the center of this fight is the element "Elex". A precious, limited resource that arrived with the meteor, Elex can power machines, open the door to magic, or re-sculpt life into new, different forms. But which of these choices should be the future of Magellan? Can technology, or magic save this world? Or will this new power destroy all those left alive amongst the ruins?  ELEX is an action, role-playing open world game for PC and Consoles, developed by Piranha Bytes, creators of the award winning Gothic series and is set in a brand new, post-apocalyptic, Science-Fantasy universe where magic meets mechs.  Collector''s Edition Contents:  Premium Quality Display Box  Mage Figurine  Cloth World Map  Companion Drone Amulet  Original Soundtrack CD  The Art of Elex book  "Making Of" DVD  Quick start Manual' FROM games WHERE igdb_id = 51995 ON CONFLICT (game_id, language_code) DO NOTHING;
