INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('epic-prose-special-edition', 52020, '2017-07-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co280t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s6twqinc3hwltgvjm0im.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Epic Prose: Special Edition', 'You start your adventure in the ashes of your home vowing for revenge! It doesn''t have to be violent, you can talk your way out of some battles. It can be very violent, you can kill NPCs and steal their stuff but it will make you evil! You can disarm your opponents before they wound you. Play Epic Prose Special Edition for the adventure of a lifetime! This is a remake of my game Epic Prose, it has many new features and mechanics that I did not have the time to put in, it is nearly complete and when done I will be releasing the code as a library.' FROM games WHERE igdb_id = 52020 ON CONFLICT (game_id, language_code) DO NOTHING;
