INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('overcooked-special-edition', 51998, '2017-07-27', 84, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tj1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbjj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Overcooked!: Special Edition', 'Get ready for the ultimate arcade-style couch cook-off in Overcooked: Special Edition for Nintendo Switch. Working as a team, you and your fellow chefs must prepare, cook and serve up a variety of tasty orders before the baying customers storm out in a huff. Sharpen your knives and dust off your chef’s whites, there isn’t mushroom for error and the steaks are high in these crazy kitchens! On the Nintendo Switch, you can now experience the crazy couch co-operative action of Overcooked wherever you choose. Simply remove the Nintendo Switch console from the Nintendo Switch Dock to take your culinary adventures on the road, just like our plucky chefs travelling around the Onion Kingdom! The Onion Kingdom is in danger and only the finest cooking can save it! In Overcooked players must journey through a variety of cruel and unusual kitchens on their quest to become master chefs capable of conquering an ancient edible evil which plagues the land. Overcooked Special Edition features all the exhilarating (and enraging) kitchens from the main game, as well as both expansions, ‘The Lost Morsel’ and ‘Festive Seasoning’.' FROM games WHERE igdb_id = 51998 ON CONFLICT (game_id, language_code) DO NOTHING;
