INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Tale of Two Kingdoms', 'A Tale of Two Kingdoms is a graphical adventure in the style of the classic Sierra games. Set in the world of Celtic mythology and fairy tales, it features many sidequests and alternate endings. Travel to the realm of Theylinn as the king calls on his old enemies for aid against a goblin invasion, get involved in intrigue and fairy trickery, and get stalked by an evil sorcerer who has its own agenda.' FROM games WHERE igdb_id = 29264 ON CONFLICT (game_id, language_code) DO NOTHING;
