INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mage''s Tale', 'Welcome, apprentice of the mystic arts! The corrupt wizard Gaufroi has kidnapped your master, Mage Alguin, and you are the only one who has any hope of saving him. You may be an apprentice now, but to save your master, you will need to explore ten deadly dungeons, decipher mind-bending puzzles, avoid terrifying traps, and vanquish hordes of vicious monsters. Until you are able to wield every elemental power in the palm of your hand, evil remains ascendant! It is your turn now to sling gouts of flame, javelins of ice, arcs of lightning, and swirling tempests! Don your wizard''s robe and begin your Mage''s Tale!' FROM games WHERE igdb_id = 36893 ON CONFLICT (game_id, language_code) DO NOTHING;
