INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Attentat 1942', 'Attentat 1942 tells the story of Nazi occupation from the perspective of those who experienced it firsthand. The game is built on dialogues, interactive comics, and authentic footage. Speak to eyewitnesses, live their memories, and discover the untold story of your family!' FROM games WHERE igdb_id = 27996 ON CONFLICT (game_id, language_code) DO NOTHING;
