INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Metal', 'Tiny Metal is a military themed turn-based tactics game. It''s simple yet has deep gameplay with an engaging story. Play as Artemisian Lieutenant, Nathan Gries, as he commands his units to victory against the villainous nation of Zipang. There will be several friends and enemies along the way with varied factions, units, and abilities in the 8-10 hours of single player campaign gameplay. Players will have to carefully consider varying terrain, positioning for attacks, and strategic advancements and defenses.' FROM games WHERE igdb_id = 24974 ON CONFLICT (game_id, language_code) DO NOTHING;
