INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Bug', 'Leap, slash, splash! You are the overpowered ninja hero Shadow Bug! Save your home forest from the evil factory by slicing monsters to pieces.  Shadow Bug is a new kind of platformer game with emphasis on action and speedrunning. The control scheme of the game is specifically designed for all the game modes on Nintendo Switch. You play as Shadow Bug and try to stop the evil factory from polluting your forest home. You do this by attacking on enemies and slicing them to pieces.' FROM games WHERE igdb_id = 44246 ON CONFLICT (game_id, language_code) DO NOTHING;
