INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Legion', 'Dark Legion VR is a first person shooter (FPS) and magic game. The player plays a chief officer on a space mission. The spaceship breaks down on the way back to earth, causing a forced landing onto a mysterious planet. In order to return back to earth, the player starts an expedition to search for energy source, only to find a huge conspiracy that a military troop on this planet is making mutant creatures in secret, that will be a catastrophe for human race. To protect your own race and your own planet, load your weapons and go destroy the dark legion!' FROM games WHERE igdb_id = 27574 ON CONFLICT (game_id, language_code) DO NOTHING;
