INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danganronpa V3: Killing Harmony', 'Welcome to a new world of Danganronpa, and prepare yourself for the biggest, most exhilarating episode yet. Set in a “psycho-cool” environment, a new cast of 16 characters find themselves kidnapped and imprisoned in a school. Inside, some will kill, some will die, and some will be punished. Reimagine what you thought high-stakes, fast-paced investigation was as you investigate twisted murder cases and condemn your new friends to death.' FROM games WHERE igdb_id = 12579 ON CONFLICT (game_id, language_code) DO NOTHING;
