INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruin of the Reckless', 'Ruin of the Reckless is a breakneck-paced, melee-focused roguelike brawler with very light persistent progression elements and a punishing difficulty curve. Play with a friend! "Ruin of the Reckless is a 2D retro-styled, fast-paced roguelike brawler focusing on melee combat. With light progression elements and a challenging difficulty curve, players can choose Stargrove or Stella to fight their way through a mysterious randomly generated tower, home to the most reckless of spirits. Explore the nuances of twin stick brawler gameplay, experiment with your attacks, and unleash screen clearing spells that obliterate your opponents. Ruin of the Reckless is a highly replayable and challenging game where the more you risk, the more you gain – if you survive…"' FROM games WHERE igdb_id = 28240 ON CONFLICT (game_id, language_code) DO NOTHING;
