INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reservoir Dogs: Bloody Days', 'An original top-down strategy shooter that stays true to the tense, dramatic vibe of the unforgettable movie, but offers a truly innovative twist on gameplay. Reservoir Dogs: Bloody Days users can control a cast of iconic characters, such as Mr. Blonde and Mr. White, while utilizing unique sets of passive abilities to succeed in the game''s multitude of heists. Players must navigate the game''s fast-paced action and hard-hitting twists by balancing aggressive shooting and taking cover to steal as much cash as possible for weapon upgrades and unlocking levels.' FROM games WHERE igdb_id = 27728 ON CONFLICT (game_id, language_code) DO NOTHING;
