INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('inner-chains', 12206, '2017-05-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24w1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4zpr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inner Chains', 'Inner Chains is an FPS horror embedded in an unprecedented surreal world. The objective of the player is to understand and unravel the mysteries of the mystical world while overcoming many dangers created by the biomechanical environment.  The world, in which we find ourselves in Inner Chains no longer resembles the one we know. It is the world that is hunting us – we are a small part of it trying to unravel its mysteries.  Throwing you into the dark and mysterious world, we want to make you feel lost, discover it piece by piece and learn to use it against enemies. In designing the levels, we want them always to have more than just one way to the goal. We will not walk you through it. We will only give you clues. How you handle this alien and hostile place depends entirely on you.  From forgotten, mountain ruins, through a dangerous forest where flora and fauna are our mortal enemies, to the great temples built by a mysterious caste, whose existence and objectives hide many secrets – wandering through this world you will be able to learn about the story carved in these places, and use it to fight the enemy.' FROM games WHERE igdb_id = 12206 ON CONFLICT (game_id, language_code) DO NOTHING;
